# Now let's check the test input - does it have any enclosed regions?
# Using the demo_in_raw and demo_out_raw as a template for structure

def flood_fill(grid, block_val):
    """Return mask of cells reachable from border through non-block values"""
    h, w = len(grid), len(grid[0])
    reachable = [[False]*w for _ in range(h)]

    # Stack all border cells
    stack = []
    for r in range(h):
        for c in range(w):
            if (r==0 or r==h-1 or c==0 or c==w-1) and grid[r][c] != block_val:
                stack.append((r,c))

    visited = set()
    while stack:
        r, c = stack.pop()
        if (r,c) in visited or grid[r][c] == block_val:
            continue
        reachable[r][c] = True
        visited.add((r,c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in visited and grid[nr][nc] != block_val:
                stack.append((nr,nc))

    return reachable

